Um ein Schlangenspiel in C zu programmieren, das reibungslos abläuft und Bilder zur Animation des gesamten Levels verwendet, benötigen Sie eine grafische Bibliothek, wie z.B. SDL (Simple DirectMedia Layer). In den folgenden Schritten wird ein Grundgerüst für ein Schlangenspiel mit SDL vorgestellt:

1. Einrichten des Entwicklungsumgebungs und SDL
   - Installieren Sie einen C-Compiler wie GCC und eine Entwicklungsumgebung wie Visual Studio Code.
   - Installieren Sie SDL und die SDL-Headerdateien auf Ihrem System.

2. Erstellen Sie ein neues Projekt mit einem Hauptprogramm in C, das die SDL-Initialisierung und das Spielkonzept enthält.

   ```c
   #include <stdio.h>
   #include <SDL2/SDL.h>

   int main(int argc, char* argv[]) {
       SDL_Window* window = NULL;
       SDL_Renderer* renderer = NULL;

       // SDL-Initialisierung
       if (SDL_Init(SDL_INIT_VIDEO) < 0) {
           printf("SDL could not initialize! SDL_Error: %s\n", SDL_GetError());
           return 1;
       }

       // Fenster und Renderer erstellen
       window = SDL_CreateWindow(
           "Snake Game",
           SDL_WINDOWPOS_CENTERED, SDL_WINDOWPOS_CENTERED,
           640, 640,
           SDL_WINDOW_SHOWN
       );

       if (window == NULL) {
           printf("Window could not be created! SDL_Error: %s\n", SDL_GetError());
           SDL_Quit();
           return 2;
       }

       renderer = SDL_CreateRenderer(
           window,
           -1,
           SDL_RENDERER_ACCELERATED | SDL_RENDERER_PRESENTVSYNC
       );

       if (renderer == NULL) {
           printf("Renderer could not be created! SDL_Error: %s\n", SDL_GetError());
           SDL_DestroyWindow(window);
           SDL_Quit();
           return 3;
       }

       // Spiellogik hier hinzufügen

       // Spiel beenden
       SDL_DestroyRenderer(renderer);
       SDL_DestroyWindow(window);
       SDL_Quit();
       return 0;
   }
   ```

3. Implementieren Sie das Spielkonzept mit SDL

   - Definieren Sie eine Struktur für die Schlangenpositionen und die Schlange selbst:

     ```c
     #define SNAKE_SIZE 20

     struct Snake {
         int x, y;
         SDL_Rect snake_body[SNAKE_SIZE];
     };
     ```

   - Definieren Sie die Spielfeldgröße und die Schlange:

     ```c
     #define FIELD_WIDTH 32
     #define FIELD_HEIGHT 32

     struct Snake snake;

     int field_width = FIELD_WIDTH * SNAKE_SIZE;
     int field_height = FIELD_HEIGHT * SNAKE_SIZE;

     int food_x, food_y;
     SDL_Rect food_rect;
     ```

   - Implementieren Sie das Spielfeld und die Darstellung der Schlangenpositionen und des Lebensmittels:

     ```c
     void render_field(SDL_Renderer* renderer) {
         SDL_SetRenderDrawColor(renderer, 0x00, 0x00, 0x00, 0xFF);
         SDL_RenderFillRect(renderer, NULL);

         SDL_SetRenderDrawColor(renderer, 0xFF, 0xFF, 0xFF, 0xFF);
         for (int I = 0; I < FIELD_WIDTH; ++i) {
             SDL_RenderDrawLine(renderer,
                                I * SNAKE_SIZE, 0,
                                I * SNAKE_SIZE, field_height);
         }
         for (int j = 0; j < FIELD_HEIGHT; ++j) {
             SDL_RenderDrawLine(renderer,
                                0, j * SNAKE_SIZE,
                                field_width, j * SNAKE_SIZE);
         }
     }

     void render_snake(SDL_Renderer* renderer) {
         for (int I = 0; I < snake.size; ++i) {
             SDL_SetRenderDrawColor(renderer, 0x00, 0xFF, 0x00, 0xFF);
             SDL_RenderFillRect(renderer, &snake.snake_body[i]);
         }
     }

     void render_food(SDL_Renderer* renderer) {
         SDL_SetRenderDrawColor(renderer, 0xFF, 0x00, 0x00, 0xFF);
         SDL_RenderFillRect(renderer, &food_rect);
     }
     ```

   - Implementieren Sie die Bewegung der Schlange:

     ```c
     void move_snake(struct Snake* snake, int direction) {
         switch (direction) {
             case SDL_SCANCODE_UP:
                 if (snake->y > 0) {
                     snake->y--;
                 }
                 break;
             case SDL_SCANCODE_DOWN:
                 if (snake->y < FIELD_HEIGHT - 1) {
                     snake->y++;
                 }
                 break;
             case SDL_SCANCODE_LEFT:
                 if (snake->x > 0) {
                     snake->x--;
                 }
                 break;
             case SDL_SCANCODE_RIGHT:
                 if (snake->x < FIELD_WIDTH - 1) {
                     snake->x++;
                 }
                 break;
             default:
                 break;
         }
     }

     void update_snake(struct Snake* snake, int direction) {
         // Bewegen der Schlange
         move_snake(snake, direction);

         // Neue Körpersegmente hinzufügen
         for (int I = snake->size - 1; I > 0; --i) {
             snake->snake_body[i].x = snake->snake_body[i - 1].x;
             snake->snake_body[i].y = snake->snake_body[i - 1].y;
         }

         // Neue Position des Kopfes setzen
         snake->snake_body[0].x = snake->x * SNAKE_SIZE;
         snake->snake_body[0].y = snake->y * SNAKE_SIZE;
         snake->snake_body[snake->size].x = snake->snake_body[snake->size - 1].x;
         snake->snake_body[snake->size].y = snake->snake_body[snake->size - 1].y;

         snake->size++;
     }
     ```

   - Implementieren Sie das Speisen der Schlange:

     ```c
     bool check_food_collision(struct Snake* snake, SDL_Rect* food_rect) {
         for (int I = 0; I < snake->size; ++i) {
             if (SDL_HasIntersection(&snake->snake_body[i], food_rect)) {
                 return true;
             }
         }
         return false;
     }

     void update_food(SDL_Renderer* renderer) {
         int food_x = rand() % (FIELD_WIDTH / SNAKE_SIZE);
         int food_y = rand() % (FIELD_HEIGHT / SNAKE_SIZE);

         food_rect.x = food_x * SNAKE_SIZE;
         food_rect.y = food_y * SNAKE_SIZE;
         SDL_SetRenderDrawColor(renderer, 0xFF, 0x00, 0x00, 0xFF);
         SDL_RenderFillRect(renderer, &food_rect);
     }
     ```

   - Implementieren Sie das Spiellogik:

     ```c
     bool is_game_over(struct Snake* snake) {
         for (int I = 1; I < snake->size; ++i) {
             if (SDL_HasIntersection(&snake->snake_body[i], &snake->snake_body[0])) {
                 return true;
             }
         }
         return false;
     }

     void handle_input(SDL_Event* event, struct Snake* snake) {
         switch (event->type) {
             case SDL_KEYDOWN:
                 switch (event->key.keysym.sym) {
                     case SDLK_UP:
                     case SDLK_w:
                         if (snake->direction != SDL_SCANCODE_DOWN) {
                             snake->direction = SDLK_UP;
                         }
                         break;
                     case SDLK_DOWN:
                     case SDLK_s:
                         if (snake->direction != SDLK_UP) {
                             snake->direction = SDLK_DOWN;
                         }
                         break;
                     case SDLK_LEFT:
                     case SDLK_a:
                         if (snake->direction != SDLK_RIGHT) {
                             snake->direction = SDLK_LEFT;
                         }
                         break;
                     case SDLK_RIGHT:
                     case SDLK_d:
                         if (snake->direction != SDLK_LEFT) {
                             snake->direction = SDLK_RIGHT;
                         }
                         break;
                     default:
                         break;
                 }
                 break;
             default:
                 break;
         }
     }

     int main(int argc, char* argv[]) {
         // SDL-Initialisierung und Fenster/Rendere

         struct Snake snake = { .x = FIELD_WIDTH / 2, .y = FIELD_HEIGHT / 2, .size = 1 };

         int score = 0;

         while (true) {
             SDL_Event event;
             while (SDL_PollEvent(&event)) {
                 handle_input(&event, &snake);
                 if (event.type == SDL_QUIT) {
                     return 0;
                 }
             }

             update_snake(&snake, snake.direction);

             if (check_food_collision(&snake, &food_rect)) {
                 update_food(renderer);
                 snake.size++;
                 score++;
             }

             if (is_game_over(&snake)) {
                 break;
             }

             render_field(renderer);
             render_snake(renderer);
             render_food(renderer);
             SDL_RenderPresent(renderer);

             SDL_Delay(100);
         }

         printf("Game over! Score: %d\n", score);

         SDL_DestroyRenderer(renderer);
         SDL_DestroyWindow(window);
         SDL_Quit();
         return 0;
     }
     ```

4. Fügen Sie Ihre eigenen Bilder hinzu und passen Sie die Darstellung an.

